import csv
import io
import re


def _read_records(raw_csv):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = []
    try:
        for record in reader:
            records.append(record)
    except csv.Error:
        pass
    return records


def _looks_like_header(record, width):
    if len(record) != width or not record:
        return False
    first = record[0].lstrip("\ufeff").strip()
    second = record[1].strip() if len(record) > 1 else ""
    if not first or not second:
        return False
    if re.match(r"^\d", first):
        return False
    if re.match(r"^\d", second):
        return False
    return bool(re.search(r"[A-Za-z]", first) and re.search(r"[A-Za-z]", second))


def _normalize_header(record, width):
    values = list(record[:width])
    if len(values) < width:
        values.extend([""] * (width - len(values)))
    if values:
        values[0] = values[0].lstrip("\ufeff")
    return values


def _key_name(value):
    return re.sub(r"[^a-z0-9]+", "", value.casefold())


def _extract_embedded_mapping(value):
    if not isinstance(value, str):
        return {}
    pattern = re.compile(
        r"""["']?\s*([^"'{}:,]+?)\s*["']?\s*:\s*["']([^"']*)["']"""
    )
    result = {}
    for match in pattern.finditer(value):
        key = match.group(1).strip()
        result[key] = match.group(2)
    return result


def _repair_record(record, header, width):
    if len(record) == width:
        return list(record)

    if len(record) > width:
        repaired = list(record[:width - 1])
        repaired.append(",".join(record[width - 1:]))
        return repaired

    header_positions = {}
    for index, name in enumerate(header):
        normalized = _key_name(name)
        if normalized and normalized not in header_positions:
            header_positions[normalized] = index

    for object_index, value in enumerate(record):
        mapping = _extract_embedded_mapping(value)
        if not mapping:
            continue

        mapped_positions = {}
        for key, mapped_value in mapping.items():
            position = header_positions.get(_key_name(key))
            if position is not None:
                mapped_positions[position] = mapped_value

        if not mapped_positions:
            continue

        repaired = [""] * width
        for index in range(min(object_index, len(record))):
            repaired[index] = record[index]

        for position, mapped_value in mapped_positions.items():
            if 0 <= position < width:
                repaired[position] = mapped_value

        next_position = max(
            [object_index] + list(mapped_positions.keys())
        ) + 1
        trailing = record[object_index + 1:]
        for value_index, value in enumerate(trailing):
            position = next_position + value_index
            if position >= width:
                break
            repaired[position] = value
        return repaired

    repaired = list(record)
    repaired.extend([""] * (width - len(repaired)))
    return repaired[:width]


def parse_csv(raw_csv: str):
    expected_width = 9
    records = _read_records(raw_csv)

    header_index = None
    for index, record in enumerate(records):
        if _looks_like_header(record, expected_width):
            header_index = index
            break

    if header_index is None:
        for index, record in enumerate(records):
            if len(record) == expected_width and any(
                re.search(r"[A-Za-z]", field or "") for field in record
            ):
                header_index = index
                break

    if header_index is None:
        header = [""] * expected_width
        data_records = records
    else:
        header = _normalize_header(records[header_index], expected_width)
        data_records = records[header_index + 1:]

    rows = []
    for record in data_records:
        if not record or (len(record) == 1 and record[0] == ""):
            continue
        rows.append(_repair_record(record, header, expected_width))

    return {"columns": header, "rows": rows}
